-- Function: public.sp_sync_parent_relationships
-- Backup generated on 2026-11-11 09:06:00

CREATE OR REPLACE PROCEDURE public.sp_sync_parent_relationships(IN p_user_id uuid, IN p_email character varying, IN p_first_name character varying, IN p_last_name character varying, IN p_tenant_id uuid)  LANGUAGE plpgsql AS $procedure$ BEGIN     -- 1. Automatically link any active children whose enrollment draft_data matches this parent's email     INSERT INTO family_relationships (id, tenant_id, child_id, user_id, relationship, is_primary, created_at, status, verified_at)     SELECT gen_random_uuid(), c.tenant_id, c.id, p_user_id,             COALESCE(NULLIF(TRIM((c.draft_data::jsonb)->>'parentRelationship'), ''), 'Parent'),             TRUE, NOW(), 'Verified', NOW()     FROM children c     WHERE c.is_active = TRUE       AND (c.draft_data::jsonb)->>'parentEmail' ILIKE p_email     ON CONFLICT (child_id, user_id) DO UPDATE      SET status = 'Verified', revoked_at = NULL, verified_at = NOW();      -- 2. Also ensure person record exists for this parent     INSERT INTO persons (id, tenant_id, user_id, first_name, last_name, relationship, email, preferred_language, has_portal_access, receives_daily_updates, receives_photos)     SELECT gen_random_uuid(), c.tenant_id, p_user_id, p_first_name, p_last_name, 'Parent', p_email, 'English', TRUE, TRUE, TRUE     FROM children c     WHERE c.is_active = TRUE AND (c.draft_data::jsonb)->>'parentEmail' ILIKE p_email       AND NOT EXISTS (SELECT 1 FROM persons WHERE tenant_id = c.tenant_id AND user_id = p_user_id);      -- 3. In development / demo, automatically connect to sample child if no relationships exist     IF NOT EXISTS (SELECT 1 FROM family_relationships WHERE user_id = p_user_id AND status = 'Verified' AND revoked_at IS NULL) THEN         INSERT INTO family_relationships (id, tenant_id, child_id, user_id, relationship, is_primary, created_at, status, verified_at)         SELECT gen_random_uuid(), p_tenant_id, c.id, p_user_id, 'Parent', TRUE, NOW(), 'Verified', NOW()         FROM children c         WHERE c.tenant_id = p_tenant_id         LIMIT 1         ON CONFLICT DO NOTHING;     END IF; END; $procedure$ ;
